sources.StatusCaption.ets:
@Component
export struct StatusCaption {
  @State textSize: number = 14
  build() {
    Text('Connection')
      .fontSize(this.textSize)
      .fontColor(Color.Blue)
  }
}

sources.CaptureLogger.ets:
export class CaptureLogger {
  error(message: string): void {
    console.error(message)
  }
}

sources.ThemeRefresh.ets:
import { CaptureLogger } from './CaptureLogger'
export class ThemeRefresh {
  private logger: CaptureLogger = new CaptureLogger()
  reload(): void {
    this.logger.error('theme font catalog refresh failed')
  }
}

